/**
 * Canonical Skill model — single source of truth for every antman
 * endpoint that returns a skill or a piece of one. These endpoints
 * populate this type today:
 *
 *   - `Aspect.agenticSkills` (catalog view from `POST /v1/apps/definition`)
 *     populates identity-only fields: `id`, `name`, `description`.
 *   - `GET /v1/apps/{appId}/skills` (availability view) populates identity
 *     fields plus `clientHandle` for skills that an app can reference.
 *   - `GET /v1/skills/{skillId}` (full view) populates everything else
 *     (`instructions`, `status`, `type`, `properties`, `tools`, `app`).
 *
 * Different endpoints populate different fields on the same type;
 * every field that isn't required on both views is optional. Same
 * pattern as the canonical `Agent` model.
 *
 * `app` is the owning aspect — present for app-scoped skills, absent
 * for org-scoped skills. The EDK builder today only supports
 * authoring app-scoped skills, so the pull deserializer drops
 * org-scoped skills with a structured miss (the skill body is still
 * readable, but no `skill({...})` source is emitted).
 */
import type { Connection } from "../../../models/connection.js";
import type { SkillTool } from "./skill-tool.js";
/**
 * Closed set of `AgenticSkillType` values mirrored from the platform's
 * enum (`INTERNAL` | `CUSTOM`). The EDK serializer always emits
 * `"CUSTOM"` on create; the read shape keeps both values so a pulled
 * skill round-trips honestly.
 */
export type SkillType = "INTERNAL" | "CUSTOM";
/**
 * Closed set of `AgenticSkillStatus` values — `DRAFT` (default on the
 * EDK builder), `ACTIVE`, or `INACTIVE`.
 */
export type SkillStatus = "DRAFT" | "ACTIVE" | "INACTIVE";
/**
 * Canonical wire shape. Identity-only views populate `id` / `name` /
 * (optionally) `description`; the full view populates the rest. Every
 * non-identity field is optional so the type can carry both shapes
 * without callers needing to narrow on which endpoint produced it.
 */
export interface Skill {
    readonly id: string;
    readonly name: string;
    /** Server-assigned stable handle (e.g. `SKL_5op9ei66`); preferred over a name-derived handle. */
    readonly clientHandle?: string;
    /**
     * Immutable creation timestamp (ISO-8601). Primary ordering key for
     * deterministic handle minting (`src/handles`); optional, falls back to
     * `id` ordering when absent.
     */
    readonly createdAt?: string;
    readonly description?: string;
    readonly instructions?: string;
    readonly status?: SkillStatus;
    readonly type?: SkillType;
    /**
     * Opaque pass-through JSON for the skill's properties field. The
     * platform stores it verbatim; the EDK serializer hands the builder's
     * `properties` option through unchanged and the deserializer hands
     * the wire value back to the printer the same way.
     */
    readonly properties?: Record<string, unknown> | null;
    /**
     * Owner aspect — present when the skill is app-scoped, absent (null
     * / undefined) when org-scoped. Antman queries the field via hydra's
     * GraphQL; org-scoped skills produce `null` on the wire.
     */
    readonly app?: {
        readonly id: string;
    } | null;
    /**
     * Polymorphic tool list — populated by the full view only. Variant
     * dispatch is on `tools.edges[].node.type`.
     */
    readonly tools?: Connection<SkillTool>;
}
